NAN = float("nan")

def closec(a, b, tol: float = 1e-12) -> bool:
    a = np.asarray(a).ravel()
    if a.size != len(b):
        print('size', a.size, len(b))
        return False
    for i in range(len(b)):
        if b[i] != b[i]:
            if a[i] == a[i]:
                print('expected nan at', i, a[i])
                return False
            continue
        if abs(a[i] - b[i]) > tol * max(1.0, abs(b[i])):
            print('mismatch at', i, a[i], b[i])
            return False
    return True

y = np.cos(np.arange(60.0).reshape(30, 2) ** 1.37) * 1.5
d = np.sin(y[:, 0] * 2.0) * y[:, 1] + y[:, 0]
x = np.array([[0.1, 0.2], [0.5, -0.3], [-0.8, 0.4], [3.0, 3.0], [0.0, 0.0], [1.2, -1.1]])
y3 = np.cos(np.arange(60.0).reshape(20, 3) ** 1.3)
d3 = y3[:, 0] * y3[:, 1] - y3[:, 2] ** 2
x3 = np.array([[0.1, 0.2, 0.0], [0.5, -0.3, 0.4], [-0.2, 0.1, -0.3]])
gx, gy = np.meshgrid(np.linspace(-1.0, 1.0, 4), np.linspace(-0.5, 0.5, 3))

